import java.io.DataInputStream
import java.util.ArrayDeque
import java.util.StringTokenizer

const val UP = 0
const val DOWN = 1
const val LEFT = 2
const val RIGHT = 3
const val UPLEFT = 4
const val UPRIGHT = 5
const val DOWNLEFT = 6
const val DOWNRIGHT = 7

val dx = intArrayOf(0, 0, -1, 1, -1, 1, -1, 1)
val dy = intArrayOf(1, -1, 0, 0, 1, 1, -1, -1)

const val MAX = 5 * 30 + 5

val marked = BooleanArray(2 * MAX * 2 * MAX * 8 * 32 * 6)

fun idx(x: Int, y: Int, d: Int, l: Int, f: Int): Int =
    ((((x * (2 * MAX) + y) * 8 + d) * 32 + l) * 6 + f)

val mp = HashMap<Long, Boolean>()
val t = IntArray(100)

fun key(x: Int, y: Int): Long = x.toLong() * 100000L + y.toLong()

fun rot(dir: Int): Pair<Int, Int> {
    if (dir == UP)
        return Pair(UPLEFT, UPRIGHT)
    if (dir == DOWN)
        return Pair(DOWNLEFT, DOWNRIGHT)
    if (dir == LEFT)
        return Pair(UPLEFT, DOWNLEFT)
    if (dir == RIGHT)
        return Pair(UPRIGHT, DOWNRIGHT)
    if (dir == UPLEFT)
        return Pair(UP, LEFT)
    if (dir == UPRIGHT)
        return Pair(UP, RIGHT)
    if (dir == DOWNLEFT)
        return Pair(DOWN, LEFT)
    return Pair(DOWN, RIGHT)
}

class Node(val x: Int, val y: Int, val dir: Int, val lev: Int, val far: Int)

val Q: ArrayDeque<Node> = ArrayDeque()

fun main() {
    val br = System.`in`.bufferedReader()
    var st = StringTokenizer(br.readLine())
    fun next(): String {
        while (!st.hasMoreTokens()) st = StringTokenizer(br.readLine())
        return st.nextToken()
    }

    val n = next().toInt()
    for (i in 1..n)
        t[i] = next().toInt()

    var ans = 0
    Q.add(Node(MAX, MAX, UP, 1, 1))

    marked[idx(MAX, MAX, UP, 1, 1)] = true
    mp[key(MAX, MAX)] = true
    ans++
    while (!Q.isEmpty()) {
        val v = Q.poll()

        if (mp[key(v.x, v.y)] != true) {
            mp[key(v.x, v.y)] = true
            ans++
        }

        val lev = v.lev
        val far = v.far

        var x2 = v.x
        var y2 = v.y

        if (lev == n + 1)
            continue

        if (far != t[lev]) {
            x2 += dx[v.dir]
            y2 += dy[v.dir]
            if (marked[idx(x2, y2, v.dir, lev, far + 1)]) continue
            marked[idx(x2, y2, v.dir, lev, far + 1)] = true
            Q.add(Node(x2, y2, v.dir, lev, far + 1))
        } else {
            val dirs = rot(v.dir)
            if (!marked[idx(v.x, v.y, dirs.first, lev + 1, 0)]) {
                marked[idx(v.x, v.y, dirs.first, lev + 1, 0)] = true
                Q.add(Node(v.x, v.y, dirs.first, lev + 1, 0))
            }
            if (!marked[idx(v.x, v.y, dirs.second, lev + 1, 0)]) {
                marked[idx(v.x, v.y, dirs.second, lev + 1, 0)] = true
                Q.add(Node(v.x, v.y, dirs.second, lev + 1, 0))
            }
        }
    }
    println(ans)
}
